function dormRegisterConfirmParseDate(text) {
    if (!text) {
        return null;
    }
    var parts = text.replace(/^\s+|\s+$/g, '').split('/');
    if (parts.length !== 3) {
        return null;
    }
    var day = parseInt(parts[0], 10);
    var month = parseInt(parts[1], 10);
    var year = parseInt(parts[2], 10);
    if (!day || !month || !year || year < 1900) {
        return null;
    }
    var dt = new Date(year, month - 1, day);
    if (dt.getFullYear() !== year || dt.getMonth() !== (month - 1) || dt.getDate() !== day) {
        return null;
    }
    return dt;
}
function dormRegisterConfirmFormatDate(dt) {
    var day = dt.getDate();
    var month = dt.getMonth() + 1;
    var year = dt.getFullYear();
    return (day < 10 ? '0' : '') + day + '/' + (month < 10 ? '0' : '') + month + '/' + year;
}
function dormRegisterConfirmAddMonths(dt, months) {
    var result = new Date(dt.getTime());
    var targetMonth = result.getMonth() + months;
    var targetYear = result.getFullYear() + Math.floor(targetMonth / 12);
    var normMonth = ((targetMonth % 12) + 12) % 12;
    var lastDay = new Date(targetYear, normMonth + 1, 0).getDate();
    var targetDay = Math.min(result.getDate(), lastDay);
    result.setFullYear(targetYear, normMonth, targetDay);
    return result;
}
function dormRegisterConfirmFormatNumber(value) {
    var parts = String(Math.round(value)).split('');
    var out = '';
    var count = 0;
    for (var i = parts.length - 1; i >= 0; i--) {
        out = parts[i] + out;
        count++;
        if (count % 3 === 0 && i > 0) {
            out = '.' + out;
        }
    }
    return out;
}
