protected string FormatRoomPrice(object value)
{
    if (value == null || value == DBNull.Value)
    {
        return string.Empty;
    }

    decimal decPrice;
    if (value is decimal)
    {
        decPrice = (decimal)value;
    }
    else if (!decimal.TryParse(value.ToString(), NumberStyles.Number, CultureInfo.InvariantCulture, out decPrice))
    {
        return string.Empty;
    }

    if (decPrice <= 0)
    {
        return string.Empty;
    }

    return String.Format(CultureInfo.GetCultureInfo("vi-VN"), "{0:#,##0} đ", decPrice);
}

/// <summary>
